// Generate a componentType, covering both valid and invalid values.
// Valid set per spec: BYTE(5120), UBYTE(5121), SHORT(5122), USHORT(5123),
// INT(5124), UINT(5125), FLOAT(5126), DOUBLE(5130)
static const uint32_t kValid[] = {5120u,5121u,5122u,5123u,5124u,5125u,5126u,5130u};
unsigned int pick = *FUZZ_PARAM(unsigned int);
uint32_t componentType = (pick % 5u == 0u) ? (100000u + pick)  // sometimes invalid
                                           : kValid[pick % (sizeof(kValid)/sizeof(kValid[0]))];
int32_t sz = tinygltf::GetComponentSizeInBytes(componentType);
// Treat unknown types as error per contract.
if (sz < 0) { FUZZ_BAIL(); }
// Ensure the size is a reasonable scalar width.
FUZZ_ASSERT(sz == 1 || sz == 2 || sz == 4 || sz == 8, "Unexpected component size");

// Valid accessor types: SCALAR(1), VEC2(2), VEC3(3), VEC4(4), MAT2(4), MAT3(9), MAT4(16)
static const uint32_t kTypes[] = {1u,2u,3u,4u,5u,6u,7u};
unsigned int pick = *FUZZ_PARAM(unsigned int);
uint32_t ty = (pick % 5u == 0u) ? (100000u + pick) : kTypes[pick % (sizeof(kTypes)/sizeof(kTypes[0]))];
int32_t n = tinygltf::GetNumComponentsInType(ty);
if (n < 0) { FUZZ_BAIL(); }
FUZZ_ASSERT(n == 1 || n == 2 || n == 3 || n == 4 || n == 9 || n == 16, "Unexpected component count");

// Randomly choose between a constructed data URI and an arbitrary string.
unsigned int mode = *FUZZ_PARAM(unsigned int) % 3u;
std::string in;
if (mode == 0u) {
  // Valid PNG data URI prefix with minimal base64 payload (empty payload is invalid, so add one byte)
  in = "data:image/png;base64,AQ=="; // single byte 0x01
} else if (mode == 1u) {
  // Octet-stream with small payload
  in = "data:application/octet-stream;base64,AA=="; // single byte 0x00
} else {
  in = FUZZ_PARAM_STR();
}
(void)tinygltf::IsDataURI(in);

// Randomize the stored type to exercise tag return.
unsigned int sel = *FUZZ_PARAM(unsigned int) % 8u;
if (sel == 0u) { /* NULL_TYPE default */ }
else if (sel == 1u) { *value = tinygltf::Value(true); }
else if (sel == 2u) { *value = tinygltf::Value(int(*FUZZ_PARAM(int))); }
else if (sel == 3u) { *value = tinygltf::Value(double(*FUZZ_PARAM(double))); }
else if (sel == 4u) { *value = tinygltf::Value(std::string("s") + FUZZ_PARAM_STR()); }
else if (sel == 5u) { std::vector<unsigned char> v = {0,1,2}; *value = tinygltf::Value(std::move(v)); }
else if (sel == 6u) { tinygltf::Value::Array a; a.push_back(tinygltf::Value(1)); *value = tinygltf::Value(std::move(a)); }
else { tinygltf::Value::Object o; o["k"] = tinygltf::Value(2); *value = tinygltf::Value(std::move(o)); }
char t = value->Type();
FUZZ_ASSERT(t >= 0 && t <= 7, "Invalid Value::Type tag");

// Ensure both true and false paths occur.
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) { *value = tinygltf::Value(true); } else { *value = tinygltf::Value(std::string("x")); }
(void)value->IsBool();

unsigned int r = *FUZZ_PARAM(unsigned int);
if ((r & 1u) != 0u) { *value = tinygltf::Value(int(*FUZZ_PARAM(int))); }
else if ((r & 2u) != 0u) { *value = tinygltf::Value(double(*FUZZ_PARAM(double))); }
else { *value = tinygltf::Value(std::string("n")); }
(void)value->IsNumber();

// Prefer numeric Value to exercise meaningful path.
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) { *value = tinygltf::Value(int(*FUZZ_PARAM(int))); } else { *value = tinygltf::Value(double(*FUZZ_PARAM(double))); }
volatile double d = value->GetNumberAsDouble();
(void)d;

if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) { *value = tinygltf::Value(double(*FUZZ_PARAM(double))); } else { *value = tinygltf::Value(int(*FUZZ_PARAM(int))); }
volatile int iv = value->GetNumberAsInt();
(void)iv;

// Exercise explicit specializations: bool and std::string.
